begin;
do $$ declare uid uuid; eng uuid; cid uuid; pid uuid; cat public.input_catalog; bid uuid; oid uuid; li uuid; received uuid; material uuid; payload jsonb; result jsonb; actual_qty numeric;begin
 select id,company_id into uid,cid from public.profiles where role='MASTER' and active limit 1;
 select id into eng from public.profiles where company_id=cid and role='ENGINEERING' and active limit 1;
 perform set_config('request.jwt.claim.sub',uid::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);
 insert into public.projects(company_id,name,code,created_by) values(cid,'OFFLINE FINANCIAL ROLLBACK','OFF-'||left(gen_random_uuid()::text,8),uid) returning id into pid;
 select * into cat from public.input_catalog where input_type='MATERIAL' and catalog_active limit 1;
 execute 'set local role authenticated';
 bid:=public.save_budget_version(pid,jsonb_build_object('title','Offline financial test','baseDate','2026-11-07','bdiConfig','{"ac":5.29,"sg":0.25,"r":1,"df":1.01,"l":8,"cp":3.65,"issBase":60,"issRate":5}'::jsonb,'items',jsonb_build_array(jsonb_build_object('inputId',cat.id,'code',cat.catalog_code,'unit',cat.unit,'source','shared','quantity',10,'unitPrice',10))));
 perform public.set_budget_baseline(pid,bid);
 oid:=(public.procurement_action('ORDER',pid,jsonb_build_object('supplier','OFFLINE TEST '||gen_random_uuid(),'items',jsonb_build_array(jsonb_build_object('code',cat.catalog_code,'source','shared','unit',cat.unit,'quantity',4,'unitPrice',12))))->>'id')::uuid;
 perform public.procurement_action('APPROVE',pid,jsonb_build_object('id',oid,'reason','Pedido aprovado para teste'));
 perform public.procurement_action('PURCHASE',pid,jsonb_build_object('id',oid));
 execute 'reset role';select id into li from public.purchase_order_items where order_id=oid;
 payload:=jsonb_build_object('clientRequestId','offline-test-'||gen_random_uuid(),'recordedAt',now()-interval '1 day','orderId',oid,'reference','NF OFFLINE','items',jsonb_build_array(jsonb_build_object('id',li,'quantity',2)));
 execute 'set local role authenticated';
 received:=(public.procurement_action('RECEIVE',pid,payload)->>'id')::uuid;
 if (public.procurement_action('RECEIVE',pid,payload)->>'id')::uuid<>received then raise exception 'Duplicate sync created another receipt';end if;
 begin perform public.procurement_action('RECEIVE',pid,jsonb_set(payload,'{items,0,quantity}','1'));raise exception 'ASSERT same key changed payload';exception when others then if sqlerrm='ASSERT same key changed payload' then raise;end if;end;
 begin perform public.procurement_action('RECEIVE',pid,jsonb_set(payload||jsonb_build_object('clientRequestId',gen_random_uuid()),'{items,0,quantity}','3'));raise exception 'ASSERT excess conflict';exception when others then if sqlerrm='ASSERT excess conflict' or position('saldo a receber' in sqlerrm)=0 then raise;end if;end;
 execute 'reset role';
 if (select count(*) from public.receipts where order_id=oid)<>1 then raise exception 'Receipt duplicated or rejected transaction left residue';end if;
 if not exists(select 1 from public.receipts where id=received and client_recorded_at is not null and client_request_id=payload->>'clientRequestId') then raise exception 'Offline metadata missing';end if;
 select material_id into material from public.receipt_items where receipt_id=received;
 select quantity into actual_qty from public.stock_items where project_id=pid and material_id=material;
 if actual_qty<>2 then raise exception 'Stock duplicate';end if;
 execute 'set local role authenticated';
 begin perform public.reserve_budget_stock(pid,material,1,'Invalid local double count');raise exception 'ASSERT local stock reserved twice';exception when others then if sqlerrm='ASSERT local stock reserved twice' or position('externo' in sqlerrm)=0 then raise;end if;end;
 perform public.procurement_action('STOCK',pid,jsonb_build_object('materialCode',cat.catalog_code,'direction','IN','quantity',3,'reason','Estoque externo de teste'));
 perform public.reserve_budget_stock(pid,material,3,'Reserva externa da obra');
 result:=public.financial_comparison_snapshot(pid,bid);
 if jsonb_array_length(result->'reservations')<>1 or (result->'reservations'->0->>'quantity')::numeric<>3 then raise exception 'Reservation snapshot missing';end if;
 begin perform public.procurement_action('STOCK',pid,jsonb_build_object('materialCode',cat.catalog_code,'direction','OUT','quantity',3,'reason','Must not consume reserved'));raise exception 'ASSERT reserved stock consumed';exception when others then if sqlerrm='ASSERT reserved stock consumed' or position('reservado' in sqlerrm)=0 then raise;end if;end;
 perform public.reserve_budget_stock(pid,material,0,'Liberação para consumo');
 perform public.procurement_action('STOCK',pid,jsonb_build_object('materialCode',cat.catalog_code,'direction','OUT','quantity',3,'reason','Consumo depois da liberação'));
 execute 'reset role';
 if (select quantity from public.stock_items where project_id=pid and material_id=material)<>2 then raise exception 'Reservation release failed';end if;
 perform public.procurement_action('STOCK',pid,jsonb_build_object('materialCode',cat.catalog_code,'direction','IN','quantity',1,'reason','Estoque externo para teste RLS'));
 perform public.reserve_budget_stock(pid,material,1,'Reserva protegida por obra',bid);
 begin perform public.reserve_budget_stock(pid,material,1,'Tela com orçamento desatualizado',gen_random_uuid());raise exception 'ASSERT stale baseline';exception when others then if sqlerrm='ASSERT stale baseline' or position('orçamento-base mudou' in sqlerrm)=0 then raise;end if;end;
 perform public.procurement_action('RECEIVE',pid,payload||jsonb_build_object('clientRequestId','other-device-'||gen_random_uuid()));
 if (select status from public.purchase_orders where id=oid)<>'RECEIVED' then raise exception 'Final receipt missing';end if;
 if (public.procurement_action('RECEIVE',pid,payload)->>'id')::uuid<>received then raise exception 'Replay after order closed must still resolve original receipt';end if;
 perform set_config('request.jwt.claim.sub',eng::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',eng,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 begin perform public.financial_comparison_snapshot(pid,bid);raise exception 'ASSERT unauthorized financial snapshot';exception when others then if sqlerrm='ASSERT unauthorized financial snapshot' then raise;end if;end;
 begin perform public.reserve_budget_stock(pid,material,1,'Unauthorized reservation');raise exception 'ASSERT unauthorized reserve';exception when others then if sqlerrm='ASSERT unauthorized reserve' then raise;end if;end;
 if exists(select 1 from public.budget_stock_reservations where project_id=pid) then raise exception 'Reservation RLS leak';end if;
 execute 'reset role';
end $$;
rollback;
